SELECT Prov_chast.Obl_name, Prov_chast.Stan_name, Prov_chast.Year, Round(Prov_chast.d_mazut,2) AS d_mazut, Round(Prov_chast.d_ugol,2) AS d_ugol, Round(Prov_chast.d_gaz,2) AS d_gaz, Round(Prov_chast.d_isk_gaz,2) AS d_isk_gaz, Round(Prov_chast.d_torf,2) AS d_torf, Round(Prov_chast.d_E,2) AS d_E, Round(Prov_chast.d_Q,2) AS d_Q, Round(Prov_chast.d_QOTR,2) AS d_QOTR, Round(Prov_chast.d_proch,2) AS d_proch, Round(Prov_chast.d_B,2) AS d_B, Round(Prov_chast.d_DON,2) AS d_DON, Round(Prov_chast.d_PODM,2) AS d_PODM, Round(Prov_chast.d_PECH,2) AS d_PECH, Round(Prov_chast.d_KUZN,2) AS d_KUZN, Round(Prov_chast.d_URAL,2) AS d_URAL, Round(Prov_chast.d_BASHK,2) AS d_BASHK, Round(Prov_chast.d_KAZAH,2) AS d_KAZAH, Round(Prov_chast.d_KAN,2) AS d_KAN, Round(Prov_chast.d_IRKUT,2) AS d_IRKUT, Round(Prov_chast.d_HAK,2) AS d_HAK, Round(Prov_chast.d_TUV,2) AS d_TUV, Round(Prov_chast.d_BUR,2) AS d_BUR, Round(Prov_chast.d_CHIT,2) AS d_CHIT, Round(Prov_chast.d_YAKUT,2) AS d_YAKUT, Round(Prov_chast.d_AMUR,2) AS d_AMUR, Round(Prov_chast.d_URG,2) AS d_URG, Round(Prov_chast.d_PRIM,2) AS d_PRIM, Round(Prov_chast.d_MAG,2) AS d_MAG, Round(Prov_chast.d_CHUKOT,2) AS d_CHUKOT, Round(Prov_chast.d_SAH,2) AS d_SAH, Round(Prov_chast.d_KAMCH,2) AS d_KAMCH
FROM [Проверка-суммы-частей] AS Prov_chast
WHERE (((Abs([Prov_chast].[d_mazut]))>0.5)) OR (((Abs([Prov_chast].[d_ugol]))>0.5)) OR (((Abs([Prov_chast].[d_gaz]))>0.5)) OR (((Abs([Prov_chast].[d_isk_gaz]))>0.5)) OR (((Abs([Prov_chast].[d_torf]))>0.5)) OR (((Abs([Prov_chast].[d_E]))>0.5)) OR (((Abs([Prov_chast].[d_Q]))>0.5)) OR (((Abs([Prov_chast].[d_QOTR]))>0.5)) OR (((Abs([Prov_chast].[d_proch]))>0.5)) OR (((Abs([Prov_chast].[d_B]))>0.5)) OR (((Abs([Prov_chast].[d_DON]))>0.5)) OR (((Abs([Prov_chast].[d_PODM]))>0.5)) OR (((Abs([Prov_chast].[d_PECH]))>0.5)) OR (((Abs([Prov_chast].[d_KUZN]))>0.5)) OR (((Abs([Prov_chast].[d_URAL]))>0.5)) OR (((Abs([Prov_chast].[d_BASHK]))>0.5)) OR (((Abs([Prov_chast].[d_KAZAH]))>0.5)) OR (((Abs([Prov_chast].[d_KAN]))>0.5)) OR (((Abs([Prov_chast].[d_IRKUT]))>0.5)) OR (((Abs([Prov_chast].[d_HAK]))>0.5)) OR (((Abs([Prov_chast].[d_TUV]))>0.5)) OR (((Abs([Prov_chast].[d_BUR]))>0.5)) OR (((Abs([Prov_chast].[d_CHIT]))>0.5)) OR (((Abs([Prov_chast].[d_YAKUT]))>0.5)) OR (((Abs([Prov_chast].[d_AMUR]))>0.5)) OR (((Abs([Prov_chast].[d_URG]))>0.5)) OR (((Abs([Prov_chast].[d_PRIM]))>0.5)) OR (((Abs([Prov_chast].[d_MAG]))>0.5)) OR (((Abs([Prov_chast].[d_CHUKOT]))>0.5)) OR (((Abs([Prov_chast].[d_SAH]))>0.5)) OR (((Abs([Prov_chast].[d_KAMCH]))>0.5));
